function normalizeUrl(url) {
  let u = url.trim();
  if (!/^https?:\/\//i.test(u)) u = "https://" + u;
  try {
    const p = new URL(u);
    let path = p.pathname.replace(/\/$/, "");
    return (p.hostname.replace(/^www\./, "") + path + p.search).toLowerCase();
  } catch { return u.toLowerCase().replace(/\/$/, ""); }
}
function metadataFor(url) {
  let host;
  try { host = new URL(/^https?:\/\//i.test(url) ? url : "https://" + url).hostname.replace(/^www\./, ""); }
  catch { host = url.replace(/^https?:\/\//, "").split("/")[0].replace(/^www\./, ""); }
  const base = KNOWN[host]
    ? { ...KNOWN[host], host }
    : (() => {
        const name = (host.split(".")[0] || host).replace(/[-_]/g, " ");
        const pretty = name.charAt(0).toUpperCase() + name.slice(1);
        // Unknown sites: no preview image available.
        return { site: pretty, title: pretty + " — " + host, desc: "Saved page from " + host + ".", host, preview: null };
      })();
  base.favicon = faviconUrl(host);
  return base;
}

const list = document.getElementById("list");
const empty = document.getElementById("empty");
const form = document.getElementById("saver");
const urlInput = document.getElementById("url");
const saveBtn = document.getElementById("saveBtn");

let bookmarks = [];

function faviconHtml(b) {
  const initial = (b.site || b.host || "?").trim().charAt(0).toUpperCase();
  if (b.loading) return '<span class="spinner"></span>';
  if (b.favicon) {
    return `<img src="${b.favicon}" alt="" onerror="this.replaceWith(document.createTextNode('${initial}'))" />`;
  }
  return initial;
}
function render() {
  empty.style.display = bookmarks.length ? "none" : "block";
  list.innerHTML = "";
  for (const b of bookmarks) {
    const card = document.createElement("div");
    card.className = "card" + (b.loading ? " saving" : " clickable");
    card.dataset.key = b.key;
    const preview = (!b.loading && b.preview)
      ? `<img class="preview" src="${b.preview}" alt="Page preview" />` : "";
    const note = (!b.loading && b.note) ? `<div class="note">${renderMarkdown(b.note)}</div>` : "";
    const tags = (!b.loading && b.tags && b.tags.length)
      ? `<div class="tags">${b.tags.map(t => `<span class="tag">${escapeHtml(t)}</span>`).join("")}</div>` : "";
    const href = openHref(b.url);
    const titleHtml = b.loading
      ? "Fetching page details…"
      : `<a href="${escapeHtml(href)}" target="_blank" rel="noopener">${escapeHtml(b.title)}</a>`;
    card.innerHTML = `
      <div class="favicon">${faviconHtml(b)}</div>
      <div class="body">
        ${preview}
        <p class="title">${titleHtml}</p>
        <p class="desc">${b.loading ? "" : escapeHtml(b.desc)}</p>
        <span class="site">${escapeHtml(b.url)}</span>
        ${note}
        ${tags}
      </div>
      ${b.loading ? "" : '<div class="col-actions"><button class="edit-btn" type="button">Edit</button></div>'}`;
    if (!b.loading) {
      // Clicking the card (or its title) opens the original page.
      card.addEventListener("click", (e) => {
        if (e.target.closest(".edit-btn") || e.target.closest("a")) return;
        window.open(href, "_blank", "noopener");
      });
      card.querySelector(".edit-btn").addEventListener("click", (e) => {
        e.stopPropagation();
        openEditor(b.key);
      });
    }
    list.appendChild(card);
  }
}
let toastTimer;
function showToast(msg) {
  let t = document.getElementById("toast");
  if (!t) { t = document.createElement("div"); t.id = "toast"; t.className = "toast"; document.body.appendChild(t); }
  t.textContent = msg;
  t.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove("show"), 2600);
}
function flashCard(key) {
  const el = list.querySelector(`[data-key="${CSS.escape(key)}"]`);
  if (!el) return;
  el.scrollIntoView({ behavior: "smooth", block: "center" });
  el.classList.remove("flash");
  void el.offsetWidth;
  el.classList.add("flash");
}
function escapeHtml(s) {
  return (s || "").replace(/[&<>"]/g, c => ({ "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;" }[c]));
}
function openHref(url) {
  return /^https?:\/\//i.test(url) ? url : "https://" + url;
}
function safeLink(url) {
  // Only allow http/https links from note markdown.
  return /^https?:\/\//i.test(url) ? url : null;
}
// Minimal, escaped-first Markdown for notes: paragraphs, bullet lists,
// links, bold, italic, inline code.
function renderMarkdown(src) {
  const lines = (src || "").split(/\r?\n/);
  let html = "", inList = false;
  const inline = (t) => {
    t = escapeHtml(t);
    t = t.replace(/`([^`]+)`/g, (_, c) => `<code>${c}</code>`);
    t = t.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (_, txt, url) => {
      const safe = safeLink(url.trim());
      return safe ? `<a href="${escapeHtml(safe)}" target="_blank" rel="noopener">${txt}</a>` : txt;
    });
    t = t.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
    t = t.replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>");
    return t;
  };
  for (const raw of lines) {
    const line = raw.trimEnd();
    const li = line.match(/^\s*[-*]\s+(.*)$/);
    if (li) {
      if (!inList) { html += "<ul>"; inList = true; }
      html += `<li>${inline(li[1])}</li>`;
    } else {
      if (inList) { html += "</ul>"; inList = false; }
      if (line.trim()) html += `<p>${inline(line)}</p>`;
    }
  }
  if (inList) html += "</ul>";
  return html;
}
function allKnownTags() {
  const set = new Map();
  for (const b of bookmarks) for (const t of (b.tags || [])) {
    const k = t.toLowerCase();
    if (!set.has(k)) set.set(k, t);
  }
  return [...set.values()];
}

form.addEventListener("submit", (e) => {
  e.preventDefault();
  const url = urlInput.value.trim();
  if (!url) return;
  const key = normalizeUrl(url);
  // Duplicate: don't add a second copy — bring up the one already saved.
  const existing = bookmarks.find(b => b.key === key);
  if (existing) {
    urlInput.value = "";
    if (existing.loading) { flashCard(key); return; }
    showToast("You already saved this — opening it so you can update it.");
    openEditor(key);
    return;
  }
  const entry = { url, key, loading: true, id: Date.now() };
  bookmarks.unshift(entry);
  urlInput.value = "";
  saveBtn.disabled = true;
  render();
  // Simulate the brief moment of fetching page details.
  setTimeout(() => {
    const meta = metadataFor(url);
    Object.assign(entry, meta, { loading: false });
    saveBtn.disabled = false;
    render();
  }, 650);
});

// --- Editor ---
const backdrop = document.getElementById("backdrop");
const editAddr = document.getElementById("editAddr");
const editTitle = document.getElementById("editTitle");
const editDesc = document.getElementById("editDesc");
const editNote = document.getElementById("editNote");
const chipbox = document.getElementById("chipbox");
const tagInput = document.getElementById("tagInput");
const suggestions = document.getElementById("suggestions");
let editingKey = null;
let draftTags = [];
let activeSuggestion = -1;

function renderChips() {
  chipbox.querySelectorAll(".chip").forEach(c => c.remove());
  draftTags.forEach((t, i) => {
    const chip = document.createElement("span");
    chip.className = "chip";
    chip.innerHTML = `${escapeHtml(t)} <button type="button" aria-label="Remove tag">×</button>`;
    chip.querySelector("button").addEventListener("click", () => {
      draftTags.splice(i, 1); renderChips();
    });
    chipbox.insertBefore(chip, tagInput);
  });
}
function addTag(value) {
  const raw = (value || "").trim().replace(/,$/, "").trim();
  if (!raw) return;
  if (!draftTags.some(t => t.toLowerCase() === raw.toLowerCase())) draftTags.push(raw);
  tagInput.value = "";
  renderChips();
  renderSuggestions();
}
function addTagFromInput() { addTag(tagInput.value); }

function currentSuggestions() {
  const q = tagInput.value.trim().toLowerCase();
  return allKnownTags().filter(t =>
    !draftTags.some(d => d.toLowerCase() === t.toLowerCase()) &&
    (q === "" ? false : t.toLowerCase().includes(q))
  ).slice(0, 6);
}
function renderSuggestions() {
  const opts = currentSuggestions();
  activeSuggestion = -1;
  if (!opts.length) { suggestions.classList.remove("open"); suggestions.innerHTML = ""; return; }
  suggestions.innerHTML = opts.map((t, i) =>
    `<div class="opt" data-i="${i}">${escapeHtml(t)}</div>`).join("");
  suggestions.querySelectorAll(".opt").forEach(el => {
    el.addEventListener("mousedown", (e) => { e.preventDefault(); addTag(opts[+el.dataset.i]); });
  });
  suggestions.classList.add("open");
}
tagInput.addEventListener("input", renderSuggestions);
tagInput.addEventListener("keydown", (e) => {
  const opts = currentSuggestions();
  if (e.key === "ArrowDown" && opts.length) {
    e.preventDefault(); activeSuggestion = Math.min(activeSuggestion + 1, opts.length - 1); highlightSuggestion();
  } else if (e.key === "ArrowUp" && opts.length) {
    e.preventDefault(); activeSuggestion = Math.max(activeSuggestion - 1, 0); highlightSuggestion();
  } else if (e.key === "Enter" || e.key === ",") {
    e.preventDefault();
    if (activeSuggestion >= 0 && opts[activeSuggestion]) addTag(opts[activeSuggestion]);
    else addTagFromInput();
  } else if (e.key === "Backspace" && !tagInput.value && draftTags.length) {
    draftTags.pop(); renderChips(); renderSuggestions();
  }
});
function highlightSuggestion() {
  suggestions.querySelectorAll(".opt").forEach((el, i) =>
    el.classList.toggle("active", i === activeSuggestion));
}
tagInput.addEventListener("blur", () => {
  addTagFromInput();
  suggestions.classList.remove("open");

