function openEditor(key) {
  const b = bookmarks.find(x => x.key === key);
  if (!b) return;
  editingKey = key;
  editAddr.value = b.url;
  editTitle.value = b.title || "";
  editDesc.value = b.desc || "";
  editNote.value = b.note || "";
  draftTags = (b.tags || []).slice();
  tagInput.value = "";
  renderChips();
  renderSuggestions();
  backdrop.classList.add("open");
  editTitle.focus();
}
function closeEditor() {
  backdrop.classList.remove("open");
  editingKey = null;
}
document.getElementById("cancelEdit").addEventListener("click", closeEditor);
backdrop.addEventListener("click", (e) => { if (e.target === backdrop) closeEditor(); });
document.addEventListener("keydown", (e) => { if (e.key === "Escape" && backdrop.classList.contains("open")) closeEditor(); });
document.getElementById("saveEdit").addEventListener("click", () => {
  addTagFromInput();
  const b = bookmarks.find(x => x.key === editingKey);
  if (b) {
    const newAddr = editAddr.value.trim() || b.url;
    const newKey = normalizeUrl(newAddr);
    // Guard: don't let an edited address collide with a different bookmark.
    const clash = bookmarks.find(x => x !== b && x.key === newKey);
    if (clash) {
      showToast("Another bookmark already uses that web address.");
      return;
    }
    b.url = newAddr;
    b.key = newKey;
    b.title = editTitle.value.trim() || b.title;
    b.desc = editDesc.value.trim();
    b.note = editNote.value.trim();
    b.tags = draftTags.slice();
    editingKey = newKey;
  }
  const key = editingKey;
  closeEditor();
  render();
  flashCard(key);
  showToast("Saved your changes.");
});

render();
document.body.setAttribute("data-harness-ready", "true");
